// Synthetic previews generated by the same renderer used by the portal.
import { readFile, writeFile, mkdir } from "node:fs/promises";
import vm from "node:vm";
import { makePDF, calculate } from "../tests/classic.mjs";
vm.runInThisContext(await readFile(new URL("../assets/pdf-lib.min.js", import.meta.url), "utf8"));
const output = new URL("../output/pdf/", import.meta.url);
await mkdir(output, { recursive: true });
const settings = {
  business_name: "Krishna's Construction", owner_name: "Eric Krishna",
  abn: "49 112 073 632", phone: "+61 431 101 188",
  email: "erickrishna@outlook.com", gst_registered: true,
  payment_instructions: "Please contact Eric to confirm payment details. Use your document number as the payment reference.",
};
for(const kind of ["quote", "booking", "invoice"]) {
  const d=KC.quotes.createDraft(kind,{date:"2026-10-25",settings:{invoice_due_days:14}});
  d.id="design-sample";
  d.number={quote:"KC-Q-SAMPLE",booking:"KC-B-SAMPLE",invoice:"KC-INV-SAMPLE"}[kind];
  d.status="draft";
  Object.assign(d.body,{
    title:"Custom cabinetry & installation",site_address:"Parramatta NSW - sample project",
    quote_type:"hourly",summary:"Supply and install custom cabinetry with a clean, practical finish tailored to the agreed design.",
    scope:kind==="invoice" ? [] : ["Confirm site measurements and cabinetry layout before fabrication.","Supply cabinetry and agreed hardware; install, align and finish on site.","Remove installation waste and leave the immediate work area tidy."],
    items:[{category:"labour",description:"Cabinet fabrication, installation and finishing",quantity:"10",unit:"hours",rate_cents:7500},{category:"materials",description:"Cabinet-grade timber, panels and agreed hardware",quantity:"2",unit:"sets",rate_cents:20000}],
    deposit_cents:10000,start_date:"2026-11-09",end_date:"2026-11-10",
    exclusions:kind==="quote" ? "Electrical work, plumbing and painting of surrounding surfaces are excluded unless expressly listed." : "",
    assumptions:kind==="quote" ? "The existing substrate is sound and the installation area is clear and accessible." : "",
  });
  d.totals=calculate(d.body);
  const blob=await makePDF(d,{settings,customer:{number:"KC-C-SAMPLE",data:{name:"Alex Taylor (sample customer)",billing_address:"Sydney NSW - sample address",email:"alex@example.invalid",phone:"0400 000 000"}},job:{number:"KC-J-SAMPLE"},payments:[],sample:true});
  await writeFile(new URL(`krishnas-${kind}-design.pdf`,output),new Uint8Array(await blob.arrayBuffer()));
}
console.log("Created three synthetic design samples in output/pdf.");
